import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline
import math

conv_transpose2d_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void conv_transpose2d_kernel(
    const float* input, const float* weight,
    float* output,
    int batch_size, int in_channels, int out_channels,
    int input_h, int input_w,
    int kernel_h, int kernel_w,
    int stride_h, int stride_w,
    int padding_h, int padding_w,
    int output_h, int output_w
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_elements = batch_size * out_channels * output_h * output_w;
    if (idx >= total_elements) return;

    int n = idx / (out_channels * output_h * output_w);
    int remainder = idx % (out_channels * output_h * output_w);
    int oc = remainder / (output_h * output_w);
    remainder = remainder % (output_h * output_w);
    int oh = remainder / output_w;
    int ow = remainder % output_w;

    float sum = 0.0f;

    for (int ic = 0; ic < in_channels; ++ic) {
        for (int kh = 0; kh < kernel_h; ++kh) {
            for (int kw = 0; kw < kernel_w; ++kw) {
                int ih_tmp = oh + padding_h - kh;
                if (ih_tmp % stride_h != 0) continue;
                int ih = ih_tmp / stride_h;
                if (ih < 0 || ih >= input_h) continue;

                int iw_tmp = ow + padding_w - kw;
                if (iw_tmp % stride_w != 0) continue;
                int iw = iw_tmp / stride_w;
                if (iw < 0 || iw >= input_w) continue;

                int input_idx = n * (in_channels * input_h * input_w) + ic * (input_h * input_w) + ih * input_w + iw;
                int weight_idx = ic * (out_channels * kernel_h * kernel_w) + oc * (kernel_h * kernel_w) + kh * kernel_w + kw;

                sum += __ldg(input + input_idx) * __ldg(weight + weight_idx);
            }
        }
    }

    atomicAdd(output + n * (out_channels * output_h * output_w) + oc * (output_h * output_w) + oh * output_w + ow, sum);
}

torch::Tensor conv_transpose2d_cuda(torch::Tensor input, torch::Tensor weight, int stride_h, int stride_w, int padding_h, int padding_w) {
    auto batch_size = input.size(0);
    auto in_channels = input.size(1);
    auto input_h = input.size(2);
    auto input_w = input.size(3);
    auto out_channels = weight.size(1);
    auto kernel_h = weight.size(2);
    auto kernel_w = weight.size(3);

    int output_h = (input_h - 1) * stride_h + kernel_h - 2 * padding_h;
    int output_w = (input_w - 1) * stride_w + kernel_w - 2 * padding_w;

    auto output = torch::zeros({batch_size, out_channels, output_h, output_w}, input.options());

    int total_elements = output.numel();
    const int block_size = 256;
    int grid_size = (total_elements + block_size - 1) / block_size;

    conv_transpose2d_kernel<<<grid_size, block_size>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size,
        in_channels,
        out_channels,
        input_h,
        input_w,
        kernel_h,
        kernel_w,
        stride_h,
        stride_w,
        padding_h,
        padding_w,
        output_h,
        output_w
    );

    return output;
}
"""

conv_transpose2d_cpp_source = """
torch::Tensor conv_transpose2d_cuda(torch::Tensor input, torch::Tensor weight, int stride_h, int stride_w, int padding_h, int padding_w);
"""

conv_transpose2d_ext = load_inline(
    name='conv_transpose2d_ext',
    cpp_sources=conv_transpose2d_cpp_source,
    cuda_sources=conv_transpose2d_source,
    functions=['conv_transpose2d_cuda'],
    verbose=True,
)

class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: tuple, stride: tuple = (1, 1), padding: tuple = (0, 0), bias: bool = False):
        super().__init__()
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding

        self.weight = nn.Parameter(torch.Tensor(
            in_channels, 
            out_channels, 
            kernel_size[0], 
            kernel_size[1]
        ))
        nn.init.kaiming_uniform_(self.weight, a=math.sqrt(5))

        if bias:
            self.bias = nn.Parameter(torch.Tensor(out_channels))
            nn.init.zeros_(self.bias)
        else:
            self.register_parameter('bias', None)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        output = conv_transpose2d_ext.conv_transpose2d_cuda(
            x, 
            self.weight, 
            self.stride[0], 
            self.stride[1], 
            self.padding[0], 
            self.padding[1]
        )
        if self.bias is not None:
            output += self.bias.view(1, -1, 1, 1)
        return output
